import { architectureChapters } from './chapters-architectures'
import { languageChapters } from './chapters-language'
import { systemsChapters } from './chapters-systems'

export interface ChapterSection {
  title: string
  paragraphs: string[]
  equation?: string
  example?: string
  question?: string
  answer?: string
}
export interface Chapter {
  prerequisites: string[]
  objectives: string[]
  sections: ChapterSection[]
  application: string
  experiment: string
  next: string
  implementation?: { language: string; code: string; explanation: string }
}

export const chapters: Record<string, Chapter> = {
  ...architectureChapters,
  ...languageChapters,
  ...systemsChapters,
  functions: {
    prerequisites: [], objectives: ['Distinguish inputs, outputs, and parameters.', 'Read an equation as an executable recipe.', 'Connect a graph, a slope, and a prediction rule.'],
    sections: [
      { title: 'Begin with a question, not an algorithm', paragraphs: ['Suppose you want to predict apartment price from floor area. An example is one observed apartment. A feature is a measurement available before prediction, such as area. A target is the quantity you want to predict, such as price. A dataset is a collection of examples. None of these words requires a neural network.', 'A model is a rule that takes features and returns a prediction. Write that rule as f(x), read as "f of x." The letter x is a placeholder for an input, not always an unknown to solve for. During inference, you know the input and want the output. During training, you know input-output examples and adjust the rule.'] },
      { title: 'Variables and parameters have different jobs', paragraphs: ['Consider f(x) = wx + b. The input x varies from apartment to apartment. The parameters w and b describe the same rule for all apartments. The weight w converts a change in area into a change in predicted price. The bias b is the prediction at x = 0.', 'An equation asserts equality. An assignment in a program changes a stored value. Mathematically, w = w - 0.1 cannot hold for a finite real number. In a program, it means replace the old weight with a new one. Subscripts such as w_old and w_new make that distinction explicit.'], equation: String.raw`f(x;w,b)=wx+b`, example: 'Measure area in tens of square meters and price in thousands. With w = 20 and b = 50, x = 4 gives 20*4 + 50 = 130. With x = 5, the same model gives 150. The weight has units of price per unit area; the bias has units of price.' },
      { title: 'A graph is a record of the rule', paragraphs: ['Place x horizontally and f(x) vertically. Every graph point is an input-output pair. For wx + b the graph is a straight line. Bias moves the whole line up or down. Weight changes its slope. A negative weight makes the output decrease as the input increases.', 'Slope means change in output divided by change in input. For a straight line it is constant. For a curved function, the slope between distant points is an average and may not describe what happens close to one input.'], equation: String.raw`\text{slope}=\frac{f(x_2)-f(x_1)}{x_2-x_1}`, question: 'If f(2) = 7 and f(5) = 16 lie on a straight line, what are w and b?', answer: 'The slope is (16 - 7)/(5 - 2) = 3. Substitute into 7 = 3*2 + b to get b = 1. Check: 3*5 + 1 = 16.' },
      { title: 'Nonlinearity means the effect depends on where you are', paragraphs: ['For f(x) = x squared, moving from 1 to 2 changes the output by 3, while moving from 2 to 3 changes it by 5. Equal input changes need not produce equal output changes. This is the simplest intuition behind nonlinearity.', 'A technically linear map satisfies f(ax + by) = af(x) + bf(y). A nonzero bias breaks this identity, so wx + b is more precisely affine. Machine-learning discussions often loosely call the whole operation linear. We will distinguish affine transformations from genuinely nonlinear activations.'] },
      { title: 'Composition turns small rules into a larger rule', paragraphs: ['Composition means feeding one function output into another. If g(x) = 2x + 1 and f(u) = 3u - 2, then f(g(x)) = 6x + 1. Two affine rules collapse into one affine rule. More such layers do not change the kind of relationship a model can express.', 'If an intermediate rule clips negative values or curves smoothly, the composition need not collapse to one line. This is why neural networks need activation functions, not just many multiplications.'], example: 'Let g(x) = max(0, x) and f(u) = 2u + 1. Their composition outputs 1 for negative x and 2x + 1 for positive x. It has two different local slopes.' },
    ], application: 'Every model in this course is a function with parameters, whether it predicts prices, recognizes images, or assigns next-token probabilities. Separating inputs from parameters makes the rest of the course easier.', experiment: 'Print outputs of 2x + 1 for x = -2, -1, 0, 1, 2. Predict the effect of changing only b, then only w. The optimization experiment is a preview; return to it after calculus.', next: 'vectors',
  },
  vectors: {
    prerequisites: ['functions'], objectives: ['Calculate vector operations component by component.', 'Interpret length, normalization, and alignment.', 'Explain why similarity depends on feature representation.'],
    sections: [
      { title: 'One example, several measurements', paragraphs: ['An apartment has area, room count, and distance from a station. Put them in an ordered list x = [area, rooms, distance]. This is a vector. Its dimension is its number of components, not its number of examples. A three-component vector lives in three-dimensional feature space even when shown on a flat screen.', 'Ordering matters. [area, rooms] and [rooms, area] are different representations unless every later operation changes convention too. Neural networks do not understand your column names; meaning comes from consistent preprocessing.'] },
      { title: 'Addition and scaling are coordinate-wise', paragraphs: ['Add vectors by adding matching components. Multiply by a scalar by multiplying every component. Geometrically, addition combines displacements. Positive scaling changes length without changing direction; negative scaling also reverses direction.', 'A linear combination scales several vectors and adds them. This is how a model combines features and how attention later combines information from different tokens. Addition combines coordinates; concatenation appends coordinates and increases dimension.'], equation: String.raw`a[2,1]+b[-1,3]=[2a-b,\ a+3b]`, example: 'With a = 2 and b = 1, the result is [3,5]. It is not [4,2,-1,3], which would be concatenation.' },
      { title: 'Derive the dot product as weighted evidence', paragraphs: ['Give each input coordinate an importance weight. Multiply each feature by its weight and add the contributions. This is the dot product. The contribution sign depends on both the feature value and the weight sign.', 'Geometrically, the dot product equals the product of lengths times the cosine of the angle. Aligned vectors give a positive result, perpendicular vectors give zero, and opposite directions give a negative result.'], equation: String.raw`a^Tb=\sum_i a_ib_i=\|a\|_2\|b\|_2\cos\theta`, example: '[2,1] dot [1,3] is 2*1 + 1*3 = 5. The coordinates contribute 2 and 3. The result is a scalar, not a vector.' },
      { title: 'Length and normalization', paragraphs: ['Euclidean magnitude generalizes the Pythagorean theorem: square components, sum, and take a square root. Squaring prevents signed coordinates from cancelling. Normalization divides every coordinate by the magnitude, preserving direction and giving length one.', 'The zero vector cannot be normalized because its length is zero. Code may reject it, return a sentinel, or add epsilon for stability. Epsilon is a numerical convention, not evidence that zero has a meaningful direction.'], equation: String.raw`\|x\|_2=\sqrt{\sum_i x_i^2},\qquad \hat x=x/\|x\|_2`, example: '[3,4] has length 5. Its normalized vector is [0.6,0.8], whose squared coordinates sum to 1.' },
      { title: 'Cosine similarity discards scale', paragraphs: ['Divide a dot product by both lengths. Positive rescaling of either nonzero vector now leaves similarity unchanged. This is useful when direction represents topic and magnitude reflects something incidental, such as document length.', 'It is not automatically the correct metric. Arbitrary feature units can dominate geometry. Standardization and learned embeddings are modeling decisions. Similarity in a poor representation remains poor similarity.'], question: 'Can [1,2] and [10,20] have cosine similarity 1 while being far apart?', answer: 'Yes. They have identical direction, so normalization maps them to the same point. Their Euclidean distance is sqrt(9 squared + 18 squared), approximately 20.12.' },
    ], application: 'Dense layers combine features with dot products; attention compares queries and keys; retrieval compares embeddings. The operation is the same, but the interpretation depends on how the vectors were built.', experiment: 'Make the vectors perpendicular, then align them and lengthen one. Watch the dot product change while cosine stays at one. Finally try a zero vector and explain why its angle is undefined.', next: 'matrices',
  },
  matrices: {
    prerequisites: ['vectors'], objectives: ['Track dimensions before calculating.', 'Expand multiplication into scalar operations.', 'Understand transpose, identity, inverse, and eigenvectors geometrically.'],
    sections: [
      { title: 'A matrix packages several dot products', paragraphs: ['A matrix has rows and columns. A 2 by 3 matrix contains two rows of three numbers. Multiplying it by a three-component column vector computes two dot products and returns a two-component vector.', 'Think of each row as a question asked of the same input. One row might detect size; another proximity. A dense layer uses this pattern with learned rather than hand-chosen rows.'], example: 'A = [[1,2],[3,4]], x = [2,1]. The outputs are 1*2 + 2*1 = 4 and 3*2 + 4*1 = 10. Both rows see the same input.' },
      { title: 'Matrix multiplication is not element-wise multiplication', paragraphs: ['Entry C at row i and column j in AB is the dot product of row i of A and column j of B. The inner dimensions must match. They tell you how many products to accumulate; the outer dimensions describe the result.', 'Element-wise multiplication instead multiplies matching positions. In NumPy, @ means matrix multiplication and * means element-wise multiplication. Equations use odot for the latter. Confusing the operations can silently change an algorithm.'], equation: String.raw`A\in\mathbb R^{m\times n},\ B\in\mathbb R^{n\times p},\quad C_{ij}=\sum_{k=1}^n A_{ik}B_{kj}`, example: 'For A = [[1,2],[3,4]] and B = [[2,0],[1,5]], AB = [[4,10],[10,20]]. The top-right entry is 1*0 + 2*5 = 10.' },
      { title: 'Columns show where basis directions go', paragraphs: ['The vectors [1,0] and [0,1] form the standard basis. Multiplying by the first selects a matrix first column; multiplying by the second selects its second column. Every vector is a linear combination of basis vectors, so the columns determine the whole transformation.', 'Diagonal matrices stretch coordinate axes. Off-diagonal entries mix coordinates. Matrices can rotate, reflect, shear, project, or collapse dimensions. Order matters: rotate then stretch generally differs from stretch then rotate.'] },
      { title: 'Transpose, identity, and inverse', paragraphs: ['Transpose swaps rows and columns. It aligns dimensions for operations such as query-key dot products. The transpose of AB equals B-transpose times A-transpose, with order reversed.', 'The identity has ones on the diagonal and zeros elsewhere, leaving every vector unchanged. An inverse undoes a square transformation when one exists. If distinct inputs collapse to the same output, an inverse cannot recover the lost information.'], equation: String.raw`AI=IA=A,\quad A^{-1}A=I,\quad (AB)^T=B^TA^T`, example: 'diag(2,3) maps [1,2] to [2,6]; diag(1/2,1/3) reverses it. diag(1,0) discards the second coordinate and has no inverse.', question: 'Should numerical code explicitly invert A to solve Ax = b?', answer: 'Usually not. A stable linear-system solver is generally more efficient and accurate. The conceptual inverse need not be constructed explicitly.' },
      { title: 'Eigenvectors are directions a map does not turn', paragraphs: ['An eigenvector is a nonzero vector mapped to a scalar multiple of itself. The scalar is its eigenvalue. A positive eigenvalue stretches or shrinks the direction; a negative one also reverses it. Not all real matrices have real eigenvectors spanning the whole space.', 'A real symmetric covariance matrix has orthonormal eigenvectors and nonnegative eigenvalues. PCA uses this special structure to find directions of variation. Repeated transformations also connect these ideas to growth and decay in recurrent networks.'], equation: String.raw`Av=\lambda v,\quad v\ne0`, example: 'For diag(2,3), [1,0] has eigenvalue 2 and [0,1] has eigenvalue 3. [1,1] is not an eigenvector: [2,3] is not its scalar multiple.' },
    ], application: 'Matrices package scalar operations for efficient hardware. Shape tracking makes network diagrams inspectable: inputs, parameters, outputs, and gradients all have compatible dimensions.', experiment: 'Try the identity matrix, then a diagonal matrix, then an off-diagonal entry. Predict each coordinate before selecting an output to inspect its dot product.', next: 'calculus',
  },
  calculus: {
    prerequisites: ['functions', 'vectors'], objectives: ['Derive a derivative from small changes.', 'Distinguish partial derivatives, gradients, and directional derivatives.', 'Multiply along paths and add across branches.'],
    sections: [
      { title: 'Why learning needs sensitivity', paragraphs: ['An error says how wrong a prediction is, but not which parameter to change. A derivative asks: if I move one quantity a tiny amount, approximately how much will another quantity change?', 'The answer is local. A large move may encounter different slopes. Optimization repeatedly measures sensitivity because its current parameter values keep changing.'] },
      { title: 'Build a derivative from an average slope', paragraphs: ['Compare f(x + h) with f(x), divide their difference by h, and shrink h toward zero. A limit is the value the expression approaches, not a command to divide by zero. When the limit exists, it defines the derivative.', 'For x squared, expand (x+h) squared, subtract x squared, and divide by h. The expression is 2x+h, which approaches 2x. This derives the familiar rule instead of asking you to memorize it.'], equation: String.raw`f'(x)=\lim_{h\to0}\frac{f(x+h)-f(x)}h,\qquad \frac{(x+h)^2-x^2}{h}=2x+h`, example: 'At x = 3, h = 0.01 gives average slope 6.01; h = 0.001 gives 6.001. The derivative is 6. The function value is 9, a different quantity.' },
      { title: 'Useful derivatives and their meaning', paragraphs: ['A constant has derivative zero. The derivative of ax+b is a. The derivative of exp(x) is exp(x), and for positive x the derivative of ln(x) is 1/x. Sums differentiate term by term.', 'The product rule accounts for both factors changing: the derivative of uv is u-prime*v + u*v-prime. At corners such as ReLU at zero, an ordinary derivative does not exist; automatic differentiation uses a chosen convention or subgradient.'] },
      { title: 'Several inputs lead to a gradient', paragraphs: ['For f(x,y), a partial derivative with respect to x varies x while holding y fixed. The gradient collects the partial derivatives in a vector whose dimension matches the input.', 'For a differentiable scalar function, the derivative along unit direction u is gradient dot u. Dot-product geometry makes this largest along the gradient and most negative in the opposite direction. This explains steepest descent under Euclidean distance.'], equation: String.raw`f(x,y)=x^2+3y^2,\quad\nabla f=[2x,6y],\quad D_uf=\nabla f^Tu`, example: 'At [1,2], the gradient is [2,12]. Moving by [-0.01,0] changes f by approximately -0.02; moving by [0,-0.01] changes it by approximately -0.12.' },
      { title: 'The chain rule connects local sensitivities', paragraphs: ['If x changes u and u changes L, then du is approximately (du/dx)dx, and dL is approximately (dL/du)du. Substitute the first into the second: the local derivatives multiply.', 'If x influences L through several paths, add their contributions. This matters for reused variables, shared weights, and residual connections. Backpropagation is a systematic implementation of this rule.'], equation: String.raw`\frac{dL}{dx}=\frac{dL}{du}\frac{du}{dx}`, example: 'Let u = 3x and L = u squared. At x = 2: u = 6, dL/du = 12, du/dx = 3, and dL/dx = 36. Direct substitution gives L = 9x squared, with derivative 18x = 36.', question: 'For L = x*x + x at x = 2, why is the derivative 5 rather than 3?', answer: 'The multiplication has two paths from x, each contributing 2. The added x contributes 1. Their sum is 5.' },
      { title: 'Check gradients numerically without training that way', paragraphs: ['Central differences estimate a derivative with [f(x+epsilon)-f(x-epsilon)]/(2 epsilon). They are useful for checking a manually written backward pass. Large epsilon causes approximation error; tiny epsilon can cause floating-point cancellation.', 'Perturbing every parameter needs approximately two forward evaluations per parameter. Reverse-mode autodiff obtains all gradients of a scalar loss in a small multiple of the forward-pass cost. This makes large-model training practical.'] },
    ], application: 'Local derivatives, multiplication along paths, and addition at branches are the calculus behind backpropagation. Jacobians later package the same rule for vector-valued functions.', experiment: 'Change the target in the backward-pass lab and predict the gradient sign. Compare a small parameter update with the predicted change. A correct derivative does not guarantee a good large step.', next: 'probability',
  },
  probability: {
    prerequisites: ['functions'], objectives: ['Distinguish events, random variables, and distributions.', 'Calculate expectation, variance, entropy, and cross entropy.', 'Explain why KL divergence is not a symmetric distance.'],
    sections: [
      { title: 'A language for uncertainty', paragraphs: ['An event is a set of possible outcomes. Its probability is between zero and one. Probabilities over mutually exclusive, exhaustive outcomes sum to one. A random variable assigns numerical values to outcomes.', 'Bernoulli represents binary events. Categorical distributions choose among several classes. Gaussian distributions describe continuous values using a mean and variance. Their bell shape is a useful assumption in some settings, not a universal law.'] },
      { title: 'Expectation and variance', paragraphs: ['Expectation multiplies each possible value by its probability and sums. It is a long-run average, not necessarily a possible individual outcome: a fair die has mean 3.5 although no face shows 3.5.', 'Variance measures squared distance from the mean. Standard deviation is its square root and has the same units as the original variable. These statistics describe different aspects of a distribution, not its entire shape.'], equation: String.raw`\mathbb E[X]=\sum_x xp(x),\quad\operatorname{Var}(X)=\mathbb E[(X-\mathbb E[X])^2]`, example: 'For a Bernoulli variable with P(X=1)=0.8, mean is 0.8 and variance is 0.8*(1-0.8)=0.16. Standard deviation is 0.4.' },
      { title: 'Density is not point probability', paragraphs: ['For continuous variables, interval probability is area under a density. A single exact value usually has probability zero. A density can exceed one as long as its total area is one.', 'A uniform density on [0,0.5] has height 2. The probability of [0,0.25] is width 0.25 times height 2, or 0.5. This matters when interpreting likelihoods of continuous observations.'] },
      { title: 'Surprise leads to entropy', paragraphs: ['Define surprise as -log(p): probable events are unsurprising; rare events are surprising. Independent probabilities multiply, while logarithms turn products into sums, so independent surprises add.', 'Entropy averages surprise under the true distribution. Natural logs give nats; base-two logs give bits. Uniform distributions maximize entropy over a fixed finite outcome set, and a certain outcome has entropy zero.'], equation: String.raw`I(x)=-\log p(x),\quad H(p)=-\sum_xp(x)\log p(x)`, question: 'Why is a fair coin harder to predict than a 99%-heads coin?', answer: 'The fair coin has no strongly preferred outcome and entropy ln(2), about 0.693 nats. The 99%-heads coin has entropy about 0.056 nats because almost every outcome is unsurprising.' },
      { title: 'Cross entropy scores predictions against reality', paragraphs: ['If outcomes follow p while the model predicts q, cross entropy averages -log q over outcomes from p. A supervised class label is represented as a one-hot target, leaving only the true class term.', 'True-class probability 0.8 gives loss 0.223; probability 0.01 gives loss 4.605. Confident errors are expensive. Cross entropy is not accuracy: two models can select the same labels but assign very different confidence.'], equation: String.raw`H(p,q)=-\sum_xp(x)\log q(x)` },
      { title: 'KL separates uncertainty from mismatch', paragraphs: ['Subtract entropy from cross entropy. The remainder is KL divergence, the excess average surprise from using q instead of p. It is nonnegative for valid distributions and zero when they agree on the relevant support.', 'KL is asymmetric. If q gives zero probability to an outcome that p considers possible, KL is infinite. Smoothing and stable log-probability calculations avoid accidental numerical versions of this problem.'], equation: String.raw`D_{KL}(p\|q)=H(p,q)-H(p)=\sum_xp(x)\log\frac{p(x)}{q(x)}`, example: 'For p=[0.5,0.5], q=[0.9,0.1], cross entropy is about 1.204. Subtract entropy 0.693 to obtain KL about 0.511 nats.' },
    ], application: 'Classification, language modeling, distillation, and policy regularization all reuse these quantities. Always identify which distribution supplies outcomes and which scores them.', experiment: 'Equalize the logits and observe maximum entropy. Increase one logit and watch entropy fall. Make class 1 unlikely and see its cross entropy rise even while another class becomes confident.', next: 'bayes',
  },
  bayes: {
    prerequisites: ['probability'], objectives: ['Derive Bayes rule from joint probability.', 'Use base rates instead of reversing conditionals.', 'Distinguish likelihood and posterior.'],
    sections: [
      { title: 'Conditioning changes the population', paragraphs: ['P(A given B) asks about A only among outcomes where B occurs. Divide the joint P(A,B) by P(B) to renormalize that population. This requires P(B)>0.', 'Independence means learning B does not change the probability of A. Conditional independence is different: variables may be independent only after another variable is known. Naive Bayes relies on this kind of modeling assumption.'], equation: String.raw`P(A\mid B)=P(A,B)/P(B)` },
      { title: 'Write the same joint two ways', paragraphs: ['P(H,E) equals both P(E given H)P(H) and P(H given E)P(E). Equate them and divide by P(E). This converts the plausibility of evidence under a hypothesis into the plausibility of the hypothesis after evidence.', 'The prior describes belief before evidence. Likelihood scores evidence under a candidate. The posterior is the updated belief. The denominator normalizes over hypotheses.'], equation: String.raw`P(H\mid E)=\frac{P(E\mid H)P(H)}{\sum_hP(E\mid h)P(h)}` },
      { title: 'Counts expose base rates', paragraphs: ['Among 10,000 items, 1% are defective: 100 defective and 9,900 nondefective. A detector finds 90% of defects and wrongly flags 10% of nondefective items.', 'It flags 90 defects and 990 nondefects. Among 1,080 flagged items, 90 are defective, so the posterior is 8.33%. High sensitivity does not make a flag conclusive when defects are rare.'], question: 'Why is the answer not 90%?', answer: '90% is P(flag given defect), measured among defective items. We want P(defect given flag), measured among flagged items. Different populations require different denominators.' },
      { title: 'Likelihood as a parameter objective', paragraphs: ['When estimating parameters, observed data stays fixed while likelihood varies with candidate parameters. Independent Bernoulli observations give a product of success and failure probabilities. Logs turn the product into a differentiable sum.', 'Maximum likelihood maximizes the data likelihood. Maximum a posteriori estimation also includes a parameter prior. Priors preferring small weights can become regularization penalties after taking negative logs.'], equation: String.raw`\log P(D\mid p)=k\log p+(n-k)\log(1-p)`, example: 'Eight successes in ten trials give maximum-likelihood p=0.8. This is an estimate, not a guarantee about the next ten trials. With little data, a prior may substantially affect inference.' },
    ], application: 'Bayesian reasoning clarifies imbalanced classification, uncertainty, and regularization. Model confidence needs calibration and appropriate deployment base rates before it can be treated as reliable probability.', experiment: 'Raise defect prevalence from 1% to 20% without changing the detector. The posterior becomes 0.18/(0.18+0.08)=69.2%. Explain why the same detector now gives more useful positive flags.', next: 'regression',
  },
  regression: {
    prerequisites: ['matrices', 'calculus', 'probability'], objectives: ['Separate model, objective, and optimizer.', 'Derive MSE gradients and perform a full update.', 'Understand validation, regularization, and generalization.'],
    sections: [
      { title: 'Learning selects a rule from a family', paragraphs: ['Supervised examples contain features and targets. Regression predicts a numerical target; classification predicts a category or class probabilities. Supervision means targets exist, not that a person watches every update.', 'A learning setup chooses a model family, an objective, and an optimizer. Affine predictions, mean squared error, and gradient descent are three separate choices. A different optimizer does not automatically change what functions the model can represent.'] },
      { title: 'Build the loss from residuals', paragraphs: ['Residual means prediction minus target. Adding residuals lets positive and negative errors cancel. Squaring makes contributions nonnegative and emphasizes large errors. Averaging keeps scale more consistent across dataset sizes.', 'MSE corresponds to maximum likelihood under independent Gaussian target noise with fixed variance. This is a modeling assumption: other noise structures may justify different losses.'], equation: String.raw`r_i=wx_i+b-y_i,\quad L=\frac1N\sum_i r_i^2` },
      { title: 'Derive and execute a complete training step', paragraphs: ['For each example, the derivative of squared residual is 2r. Residual sensitivity to w is x, and to b is 1. Multiply by the chain rule and average across examples.', 'Calculate all gradients from the same old parameters, then update. Updating one parameter and recomputing other gradients using the changed prediction would be a different procedure.'], equation: String.raw`\partial_wL=\frac2N\sum_i r_ix_i,\quad\partial_bL=\frac2N\sum_i r_i`, example: 'x=[1,2], y=[3,5], w=1, b=1 give predictions [2,3], residuals [-1,-2], loss 2.5. Gradients are -5 and -3. With rate 0.1, w=1.5 and b=1.3. New predictions [2.8,4.3] give loss 0.265.' },
      { title: 'Multiple features and computational cost', paragraphs: ['Store N examples as rows of X with d columns. A full gradient step costs O(Nd); prediction for one example costs O(d). Linear regression is efficient and interpretable but cannot express arbitrary nonlinear relationships in its supplied features.', 'Adding x squared as a feature allows curvature while keeping the model linear in learned coefficients. Least-squares solvers can also solve the objective without iterative descent. Prefer stable QR or SVD methods over explicitly inverting a matrix, especially with nearly dependent features.'], equation: String.raw`\nabla_wL=\frac2N X^T(Xw+b\mathbf1-y)` },
      { title: 'A low training loss is not the finish line', paragraphs: ['Fit weights on training data, choose hyperparameters using validation data, and reserve test data for final evaluation. Fit preprocessing only on training data. Time series often need chronological splits because random splitting can reveal future information.', 'L2 regularization adds lambda times squared weight norm and contributes 2*lambda*w to the gradient under that convention. Standardization affects how the penalty treats coordinates. Compare against a simple baseline, such as predicting the training-target mean.'], question: 'Why is fitting a scaler on the full dataset leakage?', answer: 'Validation and test values influence the fitted transformation. This uses information unavailable during training. Fit the transformation on the training split and apply it unchanged elsewhere.' },
    ], application: 'Linear regression is useful for prices, demand, and continuous measurements. More importantly, its prediction-loss-gradient-update loop is the same structure used for deep networks.', experiment: 'Implement the two-example update and print residuals, both gradients, and the new loss. Increase the learning rate until the loss rises. Explain why correct gradients do not rescue an oversized step.', next: 'classifiers',
  },
  classifiers: {
    prerequisites: ['regression', 'bayes'], objectives: ['Derive logistic classification from a score.', 'Compare neighbors and maximum-margin prediction.', 'Calculate Naive Bayes scores and identify their assumption.'],
    sections: [
      { title: 'Scores become probabilities through sigmoid', paragraphs: ['An affine score can be any real number. Sigmoid maps it to (0,1). Its log odds equal the original score. A probability threshold of 0.5 corresponds to score zero, so logistic regression has a linear decision boundary in its chosen features.', 'Train with binary cross entropy rather than hard class labels. A threshold discards confidence and is not usefully differentiable. The derivative of binary cross entropy with respect to the logit simplifies to prediction minus target.'], equation: String.raw`L=-y\log p-(1-y)\log(1-p),\quad \nabla_wL=(p-y)x`, example: 'At score 0, p=0.5. For target 1 and x=2, the weight gradient is (0.5-1)*2=-1. Descent increases the weight, making class 1 more probable.' },
      { title: 'k-nearest neighbors retains examples', paragraphs: ['Compute distances from a query to stored training points, select the k nearest, and vote. Distance-weighted variants give closer points more influence. There is little fitting beyond storing data and choosing the representation, distance, and k.', 'Small k may overfit noise; large k can blur local structure. A naive query costs O(Nd), with O(Nd) storage. Indices may help, but high-dimensional distances often concentrate. The method works when the chosen notion of local similarity is useful.'], example: 'Three neighbors with labels [1,1,0] vote for class 1. Changing an irrelevant feature scale may change the neighbors, which is why distance-based models need careful preprocessing.' },
      { title: 'SVM seeks a separating margin', paragraphs: ['With labels -1 and +1, y times the score is positive for a correctly sided prediction. A support vector machine penalizes examples inside the desired margin while controlling weight norm. Influential boundary examples are support vectors.', 'A kernel replaces explicit dot products with similarities corresponding to an implicit feature map. This permits nonlinear boundaries. Kernel training can require O(N squared) memory, and inference scales with support-vector count; linear SVM implementations can be much cheaper.'], equation: String.raw`\min_{w,b}\frac12\|w\|^2+C\sum_i\max(0,1-y_i(w^Tx_i+b))`, example: 'For label +1 and score 0.2, hinge loss is 0.8. At score 2, loss is zero. Unlike cross entropy, hinge loss stops rewarding larger scores beyond the margin.' },
      { title: 'Naive Bayes factors a difficult likelihood', paragraphs: ['Bayes rule scores each class from the prior and feature likelihoods. Assume features are conditionally independent given the class, turning a joint likelihood into a product. Use logs to turn the product into a numerically stable sum.', 'Multinomial Naive Bayes models word counts. Smoothing prevents an unseen word from making a whole document impossible. Conditional independence is often false, yet this cheap sparse-text baseline can classify well. Its probabilities may still be poorly calibrated.'], equation: String.raw`\log P(c\mid x)=\text{constant}+\log P(c)+\sum_j\log P(x_j\mid c)`, example: 'With equal class priors, P("offer"|spam)=0.3 and P("offer"|nonspam)=0.01 contribute log(30), about 3.40, toward the spam log score. Other words contribute further evidence.' },
      { title: 'Choose assumptions, not a fashionable algorithm', paragraphs: ['Logistic regression offers compact probability-oriented linear predictions. Neighbors are locally flexible but costly at query time. SVM prioritizes margins. Naive Bayes trades a strong independence assumption for efficiency.', 'Evaluate unseen examples and consider precision-recall trade-offs, calibration, latency, and memory. No algorithm is universally best. A million-example nearest-neighbor scan may be unsuitable where one O(d) linear prediction easily meets the latency budget.'] },
    ], application: 'These models remain valuable for tabular baselines, text filtering, and small-data tasks where a deep model is unnecessary.', experiment: 'Use sigmoid in the neuron lab as a logistic classifier, then switch to linear and explain why the output is no longer a probability. Separately compute a three-neighbor vote and a smoothed word likelihood.', next: 'trees',
  },
  trees: {
    prerequisites: ['probability', 'regression'], objectives: ['Calculate impurity reduction.', 'Distinguish bagging from boosting.', 'Relate depth and tree count to overfitting and cost.'],
    sections: [
      { title: 'A tree partitions feature space', paragraphs: ['A tree asks feature-threshold questions, sends an example left or right, and ends at a leaf. Classification leaves predict class distributions; regression leaves often predict a mean target.', 'Single-feature splits make axis-aligned regions. Shallow trees can underfit; deep trees can memorize examples. A greedy search chooses locally useful splits, not a provably optimal whole tree.'] },
      { title: 'Measure improvement with impurity', paragraphs: ['Gini impurity is one minus the sum of squared class probabilities. Pure nodes have zero impurity. Split gain subtracts the sample-weighted child impurities from the parent impurity. Entropy is another common criterion.', 'Regression splits reduce squared error or within-leaf variance. Sample weighting matters: a tiny pure leaf should not overwhelm a large mixed leaf.'], equation: String.raw`G=1-\sum_cp_c^2,\quad\Delta G=G_P-\frac{N_L}{N}G_L-\frac{N_R}{N}G_R`, example: 'A parent with four positives and four negatives has Gini 0.5. Children [3 positive,1 negative] and [1 positive,3 negative] each have Gini 0.375. Gain is 0.125.' },
      { title: 'Random forests benefit from different errors', paragraphs: ['Bagging trains on bootstrap samples drawn with replacement. Random forests also subsample candidate features, reducing correlation between trees. Average regression predictions or combine class probabilities.', 'Averaging helps when errors differ. Identical deterministic trees on identical data give no gain from averaging. Forests model nonlinear interactions without feature scaling, but large ensembles use memory and are harder to interpret than one tree.'] },
      { title: 'Boosting adds corrections in sequence', paragraphs: ['Gradient boosting adds a weak learner fitted to negative derivatives of the current loss with respect to predictions. For squared error with a one-half convention, these derivatives become residuals target minus prediction.', 'Shrink each correction with a learning rate. Smaller rates often need more trees. For classification, corrections may operate on logits rather than directly on probabilities. Boosting rounds depend on previous rounds; this is not independent forest training.'], equation: String.raw`F_{t+1}(x)=F_t(x)+\eta h_t(x)`, example: 'Current prediction 4, target 7, new tree correction 2, rate 0.1: next prediction is 4.2. It is not automatically 7; the learner only approximates the desired correction.' },
      { title: 'Know costs and failure modes', paragraphs: ['A depth-D tree uses approximately D comparisons per prediction; T trees cost O(TD). Training costs depend on sorting, split candidates, and histogram approximations. Forests parallelize across trees; boosting parallelizes work within sequential rounds.', 'These models are strong on structured data, but generally extrapolate poorly beyond observed feature ranges. Deep trees overfit, correlated features complicate importance scores, and target leakage can produce deceptively excellent results.'], question: 'What is the Gini gain for a perfect split of the four-positive, four-negative parent?', answer: 'Both children are pure, with impurity zero. The gain equals the parent impurity, 0.5.' },
    ], application: 'Boosted trees are effective for structured prediction, ranking, and demand forecasting. Their inductive bias often suits tabular data better than an unmodified dense network.', experiment: 'Compare the gain of a balanced impure split with a split creating one tiny pure leaf. Track child sample counts explicitly. Then simulate three boosting corrections with rate 0.1.', next: 'clustering',
  },
  clustering: {
    prerequisites: ['vectors', 'matrices', 'probability'], objectives: ['Run k-means assignment and update steps.', 'Understand PCA as retained centered variation.', 'Separate unsupervised, self-supervised, and semi-supervised signals.'],
    sections: [
      { title: 'Unlabeled does not mean objective-free', paragraphs: ['Unsupervised learning finds structure without supplied target labels. It still optimizes a criterion: grouping, compression, reconstruction, or distribution modeling. The result reflects that criterion and representation, not automatic discovery of human categories.', 'Self-supervision constructs targets from the data, such as the next token. Semi-supervision combines a labeled subset with unlabeled data. Pseudo-labeling supplies predicted labels, but confident mistakes can reinforce themselves.'] },
      { title: 'k-means alternates two easier problems', paragraphs: ['Initialize k centroids. Assign each point to its nearest centroid under squared Euclidean distance. Replace each centroid with its cluster mean. Repeat until the objective or assignments stabilize.', 'Each exact step cannot increase the objective: the mean minimizes squared error for fixed assignments, and nearest-centroid assignment minimizes it for fixed centers. This does not guarantee a global optimum. Initialization and empty-cluster handling matter.'], equation: String.raw`J=\sum_i\|x_i-\mu_{c_i}\|_2^2`, example: '[1,2,8,9] with initial centers [1,8] forms groups [1,2] and [8,9]. New centers are [1.5,8.5]. Total squared distance is 4*0.25=1.' },
      { title: 'Clustering has geometric assumptions', paragraphs: ['k-means favors compact, approximately spherical groups. Unequal densities, curved groups, and outliers can mislead it. Feature scaling changes the geometry and therefore the clusters.', 'For N examples, d dimensions, k centroids, and I iterations, naive training costs O(INkd). Cluster count is a choice, not a hidden truth the algorithm is guaranteed to reveal.'] },
      { title: 'PCA finds high-variance directions', paragraphs: ['Center features using the training mean. Among unit directions, find the one maximizing projected variance. It is the top eigenvector of the covariance matrix. Further directions maximize remaining variance while staying orthogonal.', 'Project onto r components to reduce dimension. Project back and add the mean to reconstruct. PCA is optimal for a particular linear squared-reconstruction objective, not necessarily for label prediction or nonlinear structure.'], equation: String.raw`C=\frac{X_c^TX_c}{N-1},\quad Cv_j=\lambda_jv_j,\quad Z=X_cV_r`, example: 'Centered points [-1,-1], [0,0], [1,1] lie on the diagonal. Direction [1/sqrt(2),1/sqrt(2)] retains all variation; its perpendicular direction has variance zero.' },
      { title: 'Variation and importance are different', paragraphs: ['A high-variance feature can be noise; a tiny-variance direction can contain all class information. Standardization before PCA changes the question from raw-unit variance to standardized variance. Choose deliberately.', 'Use SVD or randomized algorithms when explicitly forming a huge covariance matrix is impractical. Fit components only on training data. A 2D projection can distort distances, so attractive plots are not proof of meaningful clusters.'], question: 'How could PCA discard a feature that perfectly separates classes?', answer: 'If classes differ by a tiny vertical offset but both span a huge horizontal range, the first component may select horizontal variation. The smaller vertical variation is what predicts the label.' },
    ], application: 'Clustering supports exploration and coarse retrieval; PCA supports compression and visualization. Self-supervised objectives connect unlabeled data to modern foundation models.', experiment: 'Align one vector with [1,1] and another with [1,-1]. Verify orthogonality. Project [2,2] onto each unit direction and explain why the perpendicular coordinate is zero.', next: 'neuron',
  },
  neuron: {
    prerequisites: ['functions', 'vectors'], objectives: ['Calculate each contribution to a neuron.', 'Separate pre-activation from activation.', 'Explain what is learned and what remains fixed during prediction.'],
    sections: [
      { title: 'A neuron is a small parameterized function', paragraphs: ['A mathematical neuron receives numbers, forms a weighted sum, adds a bias, and applies an activation function. It is loosely inspired by biological signaling, but is not a realistic model of a brain cell. You can understand every operation without neuroscience.', 'Inputs are values from data or a previous layer. Weights describe how strongly those inputs contribute. Bias shifts the result independently of the input. Activation introduces a chosen nonlinear response. Training adjusts the parameters; it does not invent a new arithmetic rule at every prediction.'] },
      { title: 'Expand the weighted sum before abbreviating it', paragraphs: ['Multiply corresponding inputs and weights. Add all the products, then add bias once. Call this intermediate value z, the pre-activation. The compact dot-product notation is just an abbreviation for these scalar operations.', 'Positive weights do not universally mean positive influence: a negative input times a positive weight contributes negatively. The effect of a weight also depends on the scale of its input.'], equation: String.raw`z=w^Tx+b=\sum_{i=1}^{d}w_ix_i+b`, example: 'x=[0.7,0.2,0.9], w=[0.4,-0.7,0.2], b=0.1. Products are [0.28,-0.14,0.18]. Their sum is 0.32; adding bias gives z=0.42. There are three weights and one bias: four trainable parameters.' },
      { title: 'Activation is a separate operation', paragraphs: ['For sigmoid, compute exp(-z), add one, then take the reciprocal. Sigmoid maps any finite score to a number between zero and one. In binary classification it can represent the model probability of class 1, but calibration is not guaranteed merely by choosing sigmoid.', 'A hidden activation need not represent probability. ReLU outputs max(0,z), while tanh outputs values between -1 and 1. The choice changes both forward behavior and gradients.'], equation: String.raw`a=\sigma(z)=\frac1{1+e^{-z}}`, example: 'At z=0.42, exp(-0.42) is approximately 0.65705. The denominator is 1.65705 and the output is approximately 0.603483. Do not apply sigmoid to each product separately: sigmoid(sum) is not sum(sigmoid).' },
      { title: 'Bias moves the decision boundary', paragraphs: ['For sigmoid with threshold 0.5, the boundary occurs at z=0. Thus w dot x + b = 0 defines a hyperplane. Weight direction determines orientation and bias determines displacement. In two dimensions this is a line, not an arbitrary curved boundary.', 'With all inputs zero, z=b. Without a bias, every such boundary would pass through the origin in feature space. Bias gives flexibility but does not, by itself, make a single logistic neuron nonlinear in its decision boundary.'], question: 'If b increases by 0.5, does sigmoid output also increase by exactly 0.5?', answer: 'No. z increases from 0.42 to 0.92, but sigmoid changes from about 0.6035 to 0.7150. The nonlinear activation determines the output change.' },
      { title: 'Prediction and learning are different passes', paragraphs: ['A forward pass computes a prediction using fixed parameters. A loss compares it with a target. A backward pass computes sensitivities of that loss. An optimizer changes parameters using those sensitivities. Only the last step changes weights.', 'One neuron costs O(d) multiplication-addition work for d features and stores d+1 parameters. A network builds many such functions into a graph. Scale comes from repeating simple operations, not from making an individual neuron mysterious.'] },
    ], application: 'Logistic regression is effectively a sigmoid output neuron. Dense layers, convolutional filters, attention projections, and final vocabulary classifiers all reuse weighted sums with different sharing and connectivity rules.', experiment: 'Reproduce z=0.42 before running the lab. Set one input to zero and identify which weight stops affecting the output. Set every input to zero and verify that bias still controls the response.', next: 'activations',
    implementation: { language: 'JavaScript', explanation: 'This is the entire forward computation for the three-input example. It runs in the browser code editor.', code: `const inputs = [0.7, 0.2, 0.9];
const weights = [0.4, -0.7, 0.2];
const bias = 0.1;
const products = inputs.map((value, index) => value * weights[index]);
const preActivation = products.reduce((sum, value) => sum + value, bias);
const output = 1 / (1 + Math.exp(-preActivation));
console.log({ products, preActivation, output });` },
  },
  activations: {
    prerequisites: ['neuron', 'calculus'], objectives: ['Explain why affine layers need nonlinear activations.', 'Compare activation values and derivatives.', 'Choose output activations from the prediction task.'],
    sections: [
      { title: 'Depth without a bend collapses', paragraphs: ['Compose h=W1*x+b1 and y=W2*h+b2. Substitution gives y=(W2*W1)x+(W2*b1+b2), still one affine map. Ten such layers do not escape this function family. Nonlinearity lets different input regions behave differently.', 'An activation operates coordinate by coordinate in a standard dense layer. This keeps shapes unchanged while changing the function and its local derivative. More nonlinearity does not automatically mean easier training.'], equation: String.raw`W_2(W_1x+b_1)+b_2=(W_2W_1)x+(W_2b_1+b_2)` },
      { title: 'Sigmoid and tanh: bounded but saturating', paragraphs: ['Sigmoid is useful for binary probabilities and gates. Its derivative is a*(1-a), reaching a maximum of 0.25 at zero input. At large positive or negative inputs it saturates, leaving a small derivative.', 'Tanh is zero-centered and ranges from -1 to 1. Its derivative is 1-tanh(z) squared. It also saturates. Repeating many derivatives smaller than one can make gradients vanish, which is one reason sigmoid hidden layers are uncommon in very deep feed-forward networks.'], equation: String.raw`\sigma'(z)=\sigma(z)(1-\sigma(z)),\quad \tanh'(z)=1-\tanh^2(z)`, example: 'At z=0, sigmoid gives 0.5 with derivative 0.25; tanh gives 0 with derivative 1. At z=5, sigmoid derivative is only about 0.00665.' },
      { title: 'ReLU and its negative-side alternatives', paragraphs: ['ReLU outputs zero for negative z and z for positive z. Its derivative is zero on the negative side and one on the positive side; frameworks commonly choose zero at the corner. Positive activations avoid sigmoid-style saturation.', 'A unit that stays negative for all relevant examples receives no ordinary ReLU gradient through that branch and can become inactive. Leaky ReLU uses a small negative-side slope. ELU uses alpha*(exp(z)-1) on the negative side and z on the positive side, producing a smooth negative response when alpha=1.'], equation: String.raw`\operatorname{ReLU}(z)=\max(0,z),\quad\operatorname{LeakyReLU}(z)=\max(\alpha z,z)`, example: 'At z=-2 with alpha=0.01, ReLU outputs 0, leaky ReLU outputs -0.02, and ELU with alpha=1 outputs approximately -0.865.' },
      { title: 'Smooth gating: GELU and SiLU', paragraphs: ['GELU is z times the standard Gaussian cumulative distribution Phi(z). It softly weights an input by its location in a Gaussian-shaped transition. Many implementations use a tanh approximation rather than evaluating the exact Gaussian CDF.', 'SiLU, also called Swish with unit scale, is z*sigmoid(z). It is smooth and can be slightly negative. Modern transformer feed-forward blocks often use GELU or gated variants such as SwiGLU. They are architectural choices, not universally superior replacements in every model.'], equation: String.raw`\operatorname{GELU}(z)=z\Phi(z),\quad\operatorname{SiLU}(z)=z\sigma(z)` },
      { title: 'The output activation follows the target', paragraphs: ['Unbounded regression commonly uses a linear output. Binary classification uses one logit with a stable sigmoid-cross-entropy loss. Mutually exclusive multiclass classification uses softmax over logits. Multilabel prediction uses independent sigmoids because several labels may be true together.', 'In most training libraries, a loss named "with logits" expects raw scores and applies a numerically stable normalization internally. Adding sigmoid or softmax first may apply normalization twice or degrade stability.'], question: 'Should a photograph labeled both "outdoor" and "vehicle" use one softmax over those two labels?', answer: 'No, not if both labels can be independently true. A softmax forces competition and probabilities summing to one. Independent sigmoid outputs fit a multilabel target.' },
    ], application: 'Activation derivatives control gradient flow. Gates control how information enters memory, and output activations encode assumptions about the target distribution.', experiment: 'At the same pre-activation, compare all eight choices in the neuron lab. Predict which are bounded, which can be negative, and which have zero slope on a whole interval.', next: 'mlp',
  },
  mlp: {
    prerequisites: ['matrices', 'activations'], objectives: ['Track batch and layer dimensions.', 'Calculate a two-layer forward pass.', 'Understand XOR, parameter count, and representational capacity.'],
    sections: [
      { title: 'Layers are collections of neurons', paragraphs: ['A multilayer perceptron connects dense layers with nonlinearities. For a column-vector convention, an input of dimension d multiplied by a hidden weight matrix of shape h by d produces h hidden features. Add an h-component bias and apply activation.', 'For batched row-vector code, X has shape B by d and weight storage often has shape d by h, giving XW+b. Both conventions are valid. Mixing them without tracking shapes is not. Always state the convention before translating an equation to code.'], equation: String.raw`h=\phi(W_1x+b_1),\quad \hat y=W_2h+b_2` },
      { title: 'Walk through a complete forward pass', paragraphs: ['Use two inputs, two hidden units, and one linear output. Every hidden unit sees the whole input but has different weights. Hidden outputs then become the output neuron inputs.', 'Intermediate activations are computed features, not additional trainable parameters. They change with each example even when the weights remain fixed.'], example: 'x=[1,2], W1=[[1,-1],[0.5,1]], b1=[0,0.5]. Hidden pre-activations are [-1,3]; ReLU gives h=[0,3]. With W2=[2,-1] and b2=0.2, the prediction is -2.8.' },
      { title: 'Why hidden features can solve XOR', paragraphs: ['XOR is one when exactly one of two binary inputs is one. No single straight line separates its two positive corners from its two negative corners. A nonlinear hidden representation can change the geometry.', 'For binary inputs, define h1=ReLU(x1+x2) and h2=ReLU(x1+x2-1). The output h1-2*h2 gives 0,1,1,0 on [0,0],[1,0],[0,1],[1,1]. We have explicitly constructed a solution; training tries to discover useful parameters from examples.'], equation: String.raw`\operatorname{XOR}(x_1,x_2)=\operatorname{ReLU}(x_1+x_2)-2\operatorname{ReLU}(x_1+x_2-1)` },
      { title: 'Count parameters and work', paragraphs: ['A dense layer from d inputs to h outputs stores d*h weights and h biases. A d-to-h-to-k network therefore has d*h+h+h*k+k parameters. One-example forward work is O(dh+hk). Larger batches reuse the same parameters for more examples.', 'Width supplies more features at a stage; depth composes stages. A universal approximation theorem is an existence result under particular assumptions, not a guarantee that a small network, finite data, or an optimizer will find the desired function.'], example: 'A 2-to-3-to-1 network has 2*3+3 + 3*1+1 = 13 parameters. The batch size does not multiply the parameter count.' },
      { title: 'Capacity is not generalization', paragraphs: ['A large network may memorize training examples. Useful prediction requires appropriate data, objective, regularization, and evaluation. Training and validation loss curves help distinguish underfitting from overfitting, but do not identify every cause by themselves.', 'Feature scaling affects optimization. Initialization must break symmetry: if all hidden units have identical parameters and receive identical gradients, they remain identical rather than learning diverse features.'], question: 'Why does adding 100 identical hidden units with identical initialization not immediately create 100 different learned features?', answer: 'They compute the same activations and receive the same updates under symmetric conditions. Randomized initialization breaks that symmetry so units can specialize.' },
    ], application: 'Feed-forward blocks inside transformers are MLPs applied independently at every position with shared weights. Understanding a small dense network explains a major fraction of transformer parameter count.', experiment: 'Train XOR with a nonlinear hidden layer. Compare two versus eight hidden units, then change activation. Record both loss and decision boundary; a flexible model still needs optimization to find its solution.', next: 'losses',
  },
  losses: {
    prerequisites: ['probability', 'calculus', 'mlp'], objectives: ['Match losses to target assumptions.', 'Derive gradients for regression and classification.', 'Handle numerical stability, class imbalance, and reductions correctly.'],
    sections: [
      { title: 'Loss gives learning a numerical objective', paragraphs: ['A loss maps a prediction and target to a scalar penalty. An optimizer only sees this objective, not your intentions. If the loss rewards the wrong behavior, successful optimization can make the product worse.', 'A training objective may average data losses and add regularization. Specify whether you sum or average over examples, tokens, and output dimensions: these conventions change gradient scale and interact with learning rate.'] },
      { title: 'Squared, absolute, and Huber errors', paragraphs: ['MSE has derivative 2*(prediction-target) before averaging. It strongly penalizes large errors and corresponds to Gaussian-noise assumptions. MAE uses absolute error, with derivative sign(error) away from zero, and is less sensitive to extreme residuals.', 'Huber loss is quadratic near zero and linear beyond a threshold delta. It combines smooth local behavior with less outlier sensitivity. At zero, absolute error has a subgradient rather than a unique ordinary derivative.'], equation: String.raw`L_\delta(r)=\begin{cases}\tfrac12r^2&|r|\le\delta\\\delta(|r|-\tfrac12\delta)&|r|>\delta\end{cases}`, example: 'At residual 4 and delta=1: squared error is 16, absolute error is 4, and Huber loss is 3.5. Their derivatives are 8, 1, and 1 respectively. These scales matter when comparing optimization settings.' },
      { title: 'Binary cross entropy and its stable form', paragraphs: ['For binary target y, BCE is -y*log(p)-(1-y)*log(1-p). Compose p=sigmoid(z). The chain rule simplifies the derivative with respect to z to p-y; sigmoid saturation does not introduce an extra small factor in this combined derivative.', 'Directly taking logs of probabilities rounded to zero or one is unstable. Use a logits-based loss with max(z,0)-z*y+log(1+exp(-abs(z))). This expression avoids exponentiating a huge positive number.'], equation: String.raw`L(z,y)=\max(z,0)-zy+\log(1+e^{-|z|}),\quad\partial_zL=\sigma(z)-y` },
      { title: 'Softmax cross entropy couples the classes', paragraphs: ['Softmax exponentiates logits and divides by their sum. Subtracting the maximum logit leaves probabilities unchanged and prevents overflow. Cross entropy equals log-sum-exp(logits) minus the correct-class logit.', 'For a one-hot target vector, the gradient for class j is p_j-y_j. It raises the target score and lowers competing scores under descent. The components sum to zero, consistent with softmax being invariant to adding the same constant to every logit.'], equation: String.raw`p_j=\frac{e^{z_j-m}}{\sum_ke^{z_k-m}},\quad\partial_{z_j}L=p_j-y_j`, example: 'For probabilities [0.7,0.2,0.1] and target class 2 using one-based labels, the logit gradient is [0.7,-0.8,0.1]. The target class has the negative gradient, so descent increases its score.' },
      { title: 'Weights, smoothing, and focal loss change the objective', paragraphs: ['Class weighting changes the relative penalty of examples, useful when costs or class frequencies differ. It can change calibration and should not substitute for an appropriate decision threshold. Label smoothing replaces a one-hot target with a slightly softened distribution, discouraging extreme certainty.', 'Focal loss multiplies true-class negative log probability by (1-p_true) to a chosen power gamma, optionally with class weights. It downweights easy examples and can help dense detection with overwhelming easy negatives. It is not automatically better for ordinary balanced classification.'], equation: String.raw`L_{focal}=-\alpha(1-p_t)^\gamma\log p_t`, question: 'If most tokens in a padded batch are padding, should they contribute to language-model loss?', answer: 'No. Mask padding and average over valid targets. Otherwise the model is rewarded for predicting padding and the reported loss depends on padding amount.' },
    ], application: 'Cross entropy trains token predictors, Huber can stabilize value regression, and contrastive losses train retrieval representations. Loss selection encodes which errors count and how strongly.', experiment: 'Compare probabilities 0.5, 0.1, and 0.001 for the correct class. Calculate negative log likelihood and explain why hard accuracy alone cannot distinguish the latter two mistakes.', next: 'backprop',
  },
  backprop: {
    prerequisites: ['calculus', 'mlp', 'losses'], objectives: ['Trace local derivatives through a graph.', 'Compute a complete two-layer backward pass.', 'Distinguish backpropagation, autodiff, and optimization.'],
    sections: [
      { title: 'Backpropagation is bookkeeping for the chain rule', paragraphs: ['The forward pass builds intermediate values. The backward pass starts with derivative of loss with respect to itself equal to one, visits operations in reverse dependency order, and combines upstream sensitivity with each operation local derivative.', 'At an addition, the upstream derivative flows to both inputs. At multiplication, each input receives upstream times the other input value. If a quantity is used in several places, accumulate all contributions instead of overwriting them.'], equation: String.raw`z=uv:\quad \bar u\mathrel{+}=\bar z\,v,\quad\bar v\mathrel{+}=\bar z\,u` },
      { title: 'One sigmoid neuron, every derivative exposed', paragraphs: ['Use z=w*x+b, a=sigmoid(z), and L=one-half*(a-y) squared. Loss sensitivity to a is a-y. Activation sensitivity to z is a*(1-a). Input sensitivity of z to w is x, to b is one, and to x is w.', 'Multiplying gives the parameter gradients. The one-half in the loss cancels the factor two from differentiating the square. Without that convention, both gradients would be doubled.'], equation: String.raw`\delta=(a-y)a(1-a),\quad\partial_wL=\delta x,\quad\partial_bL=\delta,\quad\partial_xL=\delta w`, example: 'x=2, w=0.5, b=0, y=1 give z=1, a=0.731059, L=0.036165. Delta is approximately -0.052877, so dL/dw=-0.105754 and dL/db=-0.052877. At rate 0.1, new w=0.510575 and b=0.005288.' },
      { title: 'Two layers reveal gradient transport', paragraphs: ['Let h=ReLU(W1*x+b1), prediction=W2*h+b2, and use one-half squared error. The output delta is prediction-target. The W2 gradient is the outer product of output delta and h. To reach the hidden layer, multiply by W2-transpose and then by the ReLU derivative mask.', 'Every gradient must use the forward-pass weights. Changing W2 before computing the hidden gradient would backpropagate through a different network. Store activations and masks until the backward pass has consumed them.'], equation: String.raw`\delta_2=\hat y-y,\quad\delta_1=(W_2^T\delta_2)\odot\mathbf1_{z_1>0},\quad\nabla W_1=\delta_1x^T`, example: 'Reuse x=[1,2], z1=[-1,3], h=[0,3], W2=[2,-1], prediction=-2.8, target=1. Then delta2=-3.8; dW2=[0,-11.4], db2=-3.8. Before masking, hidden sensitivity is [-7.6,3.8]; after masking it is [0,3.8]. Thus dW1=[[0,0],[3.8,7.6]] and db1=[0,3.8].' },
      { title: 'Jacobians explain shapes, VJPs avoid giant matrices', paragraphs: ['A vector-valued operation has a Jacobian containing every output derivative with respect to every input. Reverse-mode differentiation multiplies an upstream row sensitivity by this Jacobian, a vector-Jacobian product, without usually constructing the full matrix.', 'For a scalar loss and many parameters, reverse mode is efficient. Forward-mode differentiation instead propagates a chosen input perturbation and can be preferable for few inputs and many outputs. Autodiff is neither symbolic algebra simplification nor finite differences: it composes exact operation-level derivatives subject to floating-point arithmetic.'] },
      { title: 'Graph lifetime and accumulation are practical concerns', paragraphs: ['Training frameworks accumulate parameter gradients by default in many APIs. Zero gradients before a new independent update unless accumulation is intentional. If using microbatches, scale losses so the accumulated gradient matches the desired batch average.', 'Detaching an intermediate stops gradient flow through that connection. Evaluation mode and disabling gradients are different: evaluation mode changes layers such as dropout, while disabling gradients controls graph construction. Backprop computes gradients; the optimizer separately uses them to update parameters.'], question: 'A parameter affects loss through two branches with gradients +3 and -1. What should be stored?', answer: 'Their sum, +2. Overwriting with the last branch or averaging them would give the wrong derivative of the full graph.' },
    ], application: 'The same reverse accumulation trains dense networks, CNNs, recurrent models, and transformers. Architecture changes the graph, not the underlying chain rule.', experiment: 'Reproduce the scalar sigmoid example. Estimate dL/dw by central differences at epsilon=0.0001 and compare with -0.105754. Then deliberately omit the activation derivative and observe the mismatch.', next: 'gradient',
    implementation: { language: 'JavaScript', explanation: 'One scalar training step with a finite-difference check. All derivatives are calculated before either parameter changes.', code: `let weight = 0.5, bias = 0;
const input = 2, target = 1, rate = 0.1;
const lossAt = candidate => {
  const prediction = 1 / (1 + Math.exp(-(candidate * input + bias)));
  return 0.5 * (prediction - target) ** 2;
};
const prediction = 1 / (1 + Math.exp(-(weight * input + bias)));
const delta = (prediction - target) * prediction * (1 - prediction);
const gradient = delta * input;
const epsilon = 0.0001;
console.log({ analytic: gradient,
  numerical: (lossAt(weight + epsilon) - lossAt(weight - epsilon)) / (2 * epsilon) });
weight -= rate * gradient;
bias -= rate * delta;
console.log({ weight, bias });` },
  },
  gradient: {
    prerequisites: ['calculus', 'backprop'], objectives: ['Derive descent from a local approximation.', 'Distinguish full-batch, stochastic, and minibatch updates.', 'Recognize learning-rate instability and noisy gradients.'],
    sections: [
      { title: 'Why subtract the gradient?', paragraphs: ['A first-order Taylor approximation predicts L(theta+delta) approximately equals L(theta)+gradient dot delta. Choose delta=-eta*gradient for positive eta. The predicted change is -eta times squared gradient norm, nonpositive.', 'The approximation ignores curvature. It justifies sufficiently small local steps under suitable smoothness conditions, not every positive learning rate. Near a minimum, curvature and noise determine whether steps settle or oscillate.'], equation: String.raw`L(\theta-\eta g)\approx L(\theta)-\eta\|g\|_2^2,\quad g=\nabla L(\theta)` },
      { title: 'A quadratic gives an exact stability condition', paragraphs: ['For L(w)=one-half*a*w squared with a positive, gradient is a*w. The update becomes w_next=(1-eta*a)w. Repeated updates shrink magnitude only when the absolute value of that multiplier is below one.', 'Thus 0<eta*a<2 gives convergence in this simple case. Values between one and two oscillate while shrinking; above two they diverge. A multidimensional quadratic is limited by the largest curvature eigenvalue.'], equation: String.raw`w_{t+1}=(1-\eta a)w_t,\qquad 0<\eta<2/a`, example: 'With a=4 and w=2, rate 0.1 gives w_next=1.2. Rate 0.4 gives -1.2 and oscillatory convergence. Rate 0.6 gives -2.8 and divergence.' },
      { title: 'Batch size controls the gradient estimate', paragraphs: ['Full-batch descent averages gradients over all training examples before each update. Stochastic descent uses one example; minibatch descent averages a subset. Under uniform sampling, minibatch gradients estimate the full-data gradient, but fluctuate from step to step.', 'An epoch means one pass through the training dataset. A step means one optimizer update. With 1,000 examples and batch size 100, an epoch has ten steps if no examples are dropped. Training loss need not fall on every noisy step.'] },
      { title: 'Curvature, conditioning, and saddles', paragraphs: ['A loss surface may be steep in one direction and flat in another. One learning rate must avoid overshooting the steep direction while making progress in the flat direction. Feature scaling, adaptive optimizers, and normalization can improve this conditioning.', 'In deep models, a zero gradient can be a minimum, maximum, saddle, or flat region. The Hessian describes second derivatives locally, but explicitly storing it costs quadratic memory in parameter count. Loss plots in two dimensions show selected slices, not the whole high-dimensional landscape.'] },
      { title: 'Schedules and stopping are part of the method', paragraphs: ['Warmup gradually increases the learning rate early in training, often helpful when optimizer statistics and representations are changing quickly. Decay reduces late-stage update size. Cosine decay and step schedules are common but require tuning for the training budget.', 'Monitor validation performance and stop based on a stated criterion. A flat training curve can indicate a tiny rate, saturation, a bug, or an objective that is already optimized. Diagnose with gradient norms, parameter updates, and small controlled examples.'], question: 'Does doubling batch size always halve training time?', answer: 'No. Hardware utilization, memory limits, data loading, update count, and optimization behavior all matter. Larger batches may need a different learning rate or more examples to reach comparable quality.' },
    ], application: 'Gradient descent is the parameter-update framework behind most deep learning. Understanding its approximation prevents treating an optimizer as a guarantee of monotonically improving loss.', experiment: 'On the 1D surface, run small and large rates from the same position. Record loss and update size. Compare a stationary point with a low-loss point; they are not synonymous.', next: 'optimizers',
  },
  optimizers: {
    prerequisites: ['gradient'], objectives: ['Calculate momentum and adaptive updates.', 'Distinguish Adam bias correction from model bias.', 'Explain weight decay, clipping, and optimizer state cost.'],
    sections: [
      { title: 'SGD sets the reference convention', paragraphs: ['Plain SGD updates theta by subtracting learning rate times the current gradient estimate. It stores no per-parameter history. Its simplicity makes it a valuable reference for understanding more elaborate methods.', 'Optimizer formulas differ in whether the moving average includes a factor 1-beta. Both conventions exist and require different learning-rate interpretation. Here momentum uses an unnormalized accumulated velocity; Adam uses normalized exponential moving averages.'], equation: String.raw`\theta_{t+1}=\theta_t-\eta g_t` },
      { title: 'Momentum accumulates a direction', paragraphs: ['Set velocity to beta times old velocity plus current gradient, then subtract eta times velocity. Repeated gradients in one direction build speed; alternating signs partially cancel. This can smooth noisy updates and traverse long shallow directions.', 'Nesterov-style momentum measures or approximates the gradient at a look-ahead point. Exact update conventions vary between libraries, so compare code rather than assuming every parameter called momentum means the same formula.'], equation: String.raw`v_t=\beta v_{t-1}+g_t,\quad\theta_t=\theta_{t-1}-\eta v_t`, example: 'With v0=0, beta=0.9, gradients 2 then 2, velocities are 2 and 3.8. At rate 0.1, successive displacements are -0.2 and -0.38.' },
      { title: 'AdaGrad and RMSProp adapt coordinate scales', paragraphs: ['AdaGrad accumulates squared gradients per coordinate and divides by their square root. Frequently updated coordinates receive smaller effective steps, useful for sparse features. The accumulated denominator only grows, which can eventually make progress too slow.', 'RMSProp instead uses an exponential moving average of squared gradients, allowing old history to fade. These methods rescale coordinates using observed gradient magnitudes. They do not compute a full Hessian inverse or model every cross-coordinate interaction.'], equation: String.raw`s_t=\rho s_{t-1}+(1-\rho)g_t^2,\quad\theta_t=\theta_{t-1}-\eta\frac{g_t}{\sqrt{s_t}+\epsilon}` },
      { title: 'Adam combines first and second moments', paragraphs: ['Adam maintains a moving average m of gradients and v of squared gradients. Starting at zero biases these averages toward zero early, so divide by 1-beta to the step power. This is optimizer initialization bias correction, unrelated to neural-layer bias parameters.', 'Use the corrected first moment divided by the square root of corrected second moment plus epsilon. Operations are coordinate-wise. Adam is not simply momentum with a universally better learning rate: its hyperparameters and generalization behavior remain task-dependent.'], equation: String.raw`m_t=\beta_1m_{t-1}+(1-\beta_1)g_t,\quad v_t=\beta_2v_{t-1}+(1-\beta_2)g_t^2,\quad\theta_t=\theta_{t-1}-\eta\frac{m_t/(1-\beta_1^t)}{\sqrt{v_t/(1-\beta_2^t)}+\epsilon}`, example: 'On step 1 with gradient 2, beta1=0.9, beta2=0.999: m=0.2 and v=0.004. Corrected moments are 2 and 4. The update is approximately -eta, not -2*eta.' },
      { title: 'AdamW separates shrinkage from the gradient transform', paragraphs: ['With plain SGD, an L2 gradient penalty can match multiplicative weight decay under a consistent coefficient convention. With adaptive methods, feeding the penalty through the adaptive denominator is generally not the same as shrinking weights directly.', 'AdamW applies decoupled weight decay, typically theta <- (1-eta*lambda)theta minus the adaptive loss-gradient update. Biases and normalization scales are often excluded by convention. Gradient clipping limits update-driving gradients but does not fix an invalid loss or replace learning-rate selection.'], equation: String.raw`g_{clip}=g\min\left(1,\frac{c}{\|g\|_2}\right)`, question: 'What extra memory does Adam require beyond model weights?', answer: 'At least two parameter-sized moment tensors, usually FP32, plus gradients and possibly master weights. Precision and implementation determine exact memory, but optimizer state can exceed low-precision weight storage.' },
    ], application: 'AdamW is common for transformers; SGD with momentum remains effective in many vision settings. Exact conventions, precision, schedules, and decay exclusions are part of a reproducible recipe.', experiment: 'Calculate the two-step momentum example manually. In the training lab compare SGD and Adam with recorded rates and initialization, recognizing that equal numerical rates need not be equivalent settings.', next: 'training',
  },
  training: {
    prerequisites: ['mlp', 'losses', 'backprop', 'optimizers'], objectives: ['Run the complete training and validation loop.', 'Explain initialization and regularization choices.', 'Diagnose underfitting, overfitting, and implementation errors.'],
    sections: [
      { title: 'The full loop has a precise order', paragraphs: ['Split data, fit preprocessing on the training split, initialize parameters, and iterate batches. For each update: clear old gradients, compute predictions, compute loss, backpropagate, optionally clip, and step the optimizer. Evaluation uses held-out data without updating weights.', 'Shuffle appropriate training datasets between epochs, but preserve ordering when the task requires it. Track seeds, data versions, architecture, optimizer settings, and checkpoints. A seed aids reproducibility but does not guarantee bit-identical results across all hardware kernels.'] },
      { title: 'Initialization controls signal scale and symmetry', paragraphs: ['Zero-initializing all hidden weights makes units symmetric. Independent random weights break symmetry, but their scale also matters. Repeated multiplication can amplify or shrink activations before any training happens.', 'Xavier initialization targets variance roughly 2/(fan_in+fan_out), often used with symmetric activations. He initialization uses roughly 2/fan_in for ReLU-like layers to compensate for inactive values. These are approximate variance arguments under simplifying independence assumptions, not exact guarantees for every architecture.'], equation: String.raw`\operatorname{Var}(W)\approx\frac2{n_{in}+n_{out}}\ \text{(Xavier)},\qquad\operatorname{Var}(W)\approx\frac2{n_{in}}\ \text{(He)}` },
      { title: 'Regularization changes what training prefers', paragraphs: ['Weight decay discourages large parameter values. Dropout randomly zeros activations during training; inverted dropout divides retained activations by keep probability so their expectation stays unchanged. At evaluation, ordinary dropout is disabled.', 'Data augmentation creates label-preserving variations when the domain permits them. Early stopping selects a checkpoint based on validation behavior. None replaces sufficient representative data. An augmentation that changes a label teaches contradictory supervision.'], example: 'With keep probability 0.8, an activation of 2 is either 0 or 2/0.8=2.5. Its expectation is 0.2*0+0.8*2.5=2. Using this random mask during standard evaluation would unnecessarily make predictions stochastic.' },
      { title: 'Read curves as evidence, not a diagnosis by themselves', paragraphs: ['High training and validation error suggests underfitting, optimization trouble, bad features, or incorrect labels. Falling training error with rising validation error suggests overfitting or distribution mismatch. Inspect examples and gradients before simply adding layers.', 'A powerful sanity check is to overfit a tiny clean batch. Failure may expose wrong targets, detached gradients, bad loss scaling, or an optimizer that is not stepping. Success proves basic fitting ability, not generalization. Compare against a trivial baseline and inspect class-level metrics.'] },
      { title: 'Batch size, accumulation, and mixed precision', paragraphs: ['Batch size trades memory, throughput, and gradient noise. Gradient accumulation sums microbatch contributions to emulate a larger update batch if loss scaling is correct. BatchNorm and random layers can still make microbatch execution differ from one large batch.', 'Mixed precision reduces storage and can accelerate matrix multiplication. Keep sensitive reductions or optimizer state at suitable precision. FP16 may require loss scaling; BF16 has a wider exponent range but lower mantissa precision. Check finite losses and gradients instead of assuming every overflow is a model issue.'], question: 'If validation performance stops improving, should you continue until training accuracy is exactly 100%?', answer: 'Not automatically. Select using the intended validation criterion and training budget. Perfect training accuracy can mean memorization rather than improved performance on future examples.' },
    ], application: 'The laboratory trains real TensorFlow.js models, but its displayed accuracy is on the generated training data. It is useful for studying fitting and boundaries, not for claiming held-out benchmark performance.', experiment: 'Use XOR, circles, and spirals. Keep a small table of width, depth, activation, optimizer, rate, epochs, and loss. Change one variable at a time. Explain where a visibly improved boundary might still fail on unseen data.', next: 'convolution',
  },
}